actor ApprovalStore {
    private var pending: [RequestID: PaymentRequest] = [:]
    func approve(_ id: RequestID, as approver: UserID) throws {
        guard var r = pending[id] else { throw Error.unknown }
        guard r.initiatedBy != approver else { throw Error.selfApproval }
        r.state = .approved(by: approver)
        pending[id] = r
    }
}
